    static void check(boolean ok,String message){SevenTaskbarRowsSmoke.check(ok,message);}
    TaskbarReorder reorder(){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField("taskbarReorder");f.setAccessible(true);return (TaskbarReorder)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
